"""Local diagnostics with an explicit privacy-safe field allowlist."""
import json
import os
import platform
from pathlib import Path

from . import model_store


def application_root():
    return Path(os.environ.get("EXPC_WLK_INSTALL_ROOT", Path(__file__).resolve().parents[3]))


def collect(engine=None, root=None):
    root = Path(root or application_root()).resolve()
    metadata_root = Path(os.environ.get("EXPC_WLK_METADATA_ROOT", root)).resolve()
    models = Path(os.environ.get("EXPC_WLK_MODEL_ROOT", root / "models")).resolve()
    release = json.loads((metadata_root / "config/release.json").read_text(encoding="utf-8"))
    model = getattr(engine, "model_key", None) or "unknown"
    revision = "unknown"
    integrity = "not installed"
    model_dir = models / model
    if model in ("small", "large-v3-turbo"):
        manifest = model_store.manifest_for(metadata_root, model)
        revision = manifest["revision"]
        if os.environ.get("EXPC_WLK_MODEL_ROOT"):
            integrity = model_store.model_status(
                metadata_root, model, verify_hashes=True, model_root=models
            )
        else:
            integrity = model_store.model_status(metadata_root, model, verify_hashes=True)
    try:
        import ctranslate2
        gpu_count = ctranslate2.get_cuda_device_count()
    except Exception:
        gpu_count = 0
    device = getattr(engine, "device", "unknown")
    compute = getattr(engine, "compute_type", "unknown")
    return {
        "version": release["version"],
        "model": model,
        "model_revision": revision,
        "model_integrity": integrity,
        "backend": "NVIDIA CUDA" if device == "cuda" else "CPU",
        "compute_type": compute,
        "detected_gpu": f"NVIDIA CUDA devices: {gpu_count}" if gpu_count else "not detected",
        "cpu": os.environ.get("PROCESSOR_IDENTIFIER", platform.processor() or "unknown"),
        "windows": platform.platform(),
        "mode": os.environ.get("EXPC_WLK_MODE", "portable"),
        "model_directory": str(model_dir),
        "update_channel": release.get("channel", "stable"),
    }


def format_report(data):
    labels = {
        "version": "EXPC-WLK version", "model": "Model", "model_revision": "Model revision",
        "model_integrity": "Model integrity", "backend": "Backend", "compute_type": "Compute type",
        "detected_gpu": "Detected GPU", "cpu": "CPU", "windows": "Windows",
        "mode": "Installation mode", "model_directory": "Model directory",
        "update_channel": "Update channel",
    }
    return "\n".join(f"{labels[key]}: {data[key]}" for key in labels) + "\n"


def copy_to_clipboard(text):
    import win32clipboard
    win32clipboard.OpenClipboard()
    try:
        win32clipboard.EmptyClipboard()
        win32clipboard.SetClipboardText(text)
    finally:
        win32clipboard.CloseClipboard()
